const requestItems = $items('Webhook', 0) || [];
const requestBody = requestItems[0]?.json?.body || {};
const now = new Date();
const iso = now.toISOString();
const baseTs = Date.now();

return $input.all().map((item, index) => ({
  json: {
    ...(item.json || {}),
    request_body: requestBody,
    qa_requested_at: iso,
    start_time: iso,
    start_ts_ms: baseTs + index
  }
}));

function toArray(value) {
  if (!value && value !== 0) return [];
  if (Array.isArray(value)) {
    return value.map(v => (v ?? '').toString().trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) {
        return parsed.map(v => (v ?? '').toString().trim()).filter(Boolean);
      }
    } catch (error) {}
    return trimmed
      .replace(/^[{\[(]/, '')
      .replace(/[}\])]/, '')
      .split(/,|
|;|\|/)
      .map(part => part.trim())
      .filter(Boolean);
  }
  if (typeof value === 'object') {
    return Object.values(value)
      .map(v => (v ?? '').toString().trim())
      .filter(Boolean);
  }
  return [];
}

function normalizeText(value) {
  return (value ?? '')
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim();
}

function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\]/g, '\$&');
}

function countOccurrences(text, phrase) {
  if (!text || !phrase) return 0;
  const escaped = escapeRegExp(phrase);
  const pattern = new RegExp(`\b${escaped.replace(/\s+/g, '\s+')}\b`, 'g');
  const matches = text.match(pattern);
  return matches ? matches.length : 0;
}

function toPlain(markdown) {
  if (!markdown) return '';
  let text = markdown.replace(//g, '');
  text = text.replace(/```[\s\S]*?```/g, ' ');
  text = text.replace(/~{3}[\s\S]*?~{3}/g, ' ');
  text = text.replace(/!\[[^\]]*\]\([^)]+\)/g, ' ');
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1');
  text = text.replace(/^>\s?/gm, '');
  text = text.replace(/[#*_`>~-]+/g, ' ');
  return text.replace(/\s+/g, ' ').trim();
}

const requestBody = ($input.first()?.json?.request_body) || {};
const metaTitleMin = Number(requestBody.meta_title_min ?? 35);
const metaTitleWarnMin = Number(requestBody.meta_title_warn_min ?? 30);
const metaTitleMax = Number(requestBody.meta_title_max ?? 60);
const metaDescriptionMin = Number(requestBody.meta_description_min ?? 110);
const metaDescriptionWarnMin = Number(requestBody.meta_description_warn_min ?? 90);
const metaDescriptionMax = Number(requestBody.meta_description_max ?? 165);
const wordCountMin = Number(requestBody.word_count_min ?? 600);
const wordCountWarn = Number(requestBody.word_count_warn ?? 550);
const densityMin = Number(requestBody.keyword_density_min ?? 0.8);
const densityWarnMin = Number(requestBody.keyword_density_warn_min ?? 0.6);
const densityMax = Number(requestBody.keyword_density_max ?? 2.5);
const densityWarnMax = Number(requestBody.keyword_density_warn_max ?? 3.0);

return $input.all().map((item) => {
  const data = item.json || {};
  const metaTitle = (data.meta_title || data.title || '').toString().trim();
  const metaDescription = (data.meta_description || '').toString().trim();
  const tags = Array.isArray(data.tags) ? data.tags : toArray(data.tags);
  const secondaryKeywords = toArray(data.keywords_secundarias);
  const mainKeyword = (data.keyword_principal || '').toString().trim();

  let content = (data.content_markdown || '').toString().replace(//g, '');
  const fm = content.match(/^---
([\s\S]*?)
---
([\s\S]*)$/);
  if (fm) {
    content = fm[2] || '';
  }

  const contentPlain = toPlain(content);
  const words = contentPlain ? contentPlain.split(/\s+/).filter(Boolean) : [];
  const calculatedWordCount = words.length;
  const finalWordCount = calculatedWordCount || Number(data.word_count) || 0;

  const normalizedContent = normalizeText(contentPlain);
  const firstHundred = normalizeText(words.slice(0, 100).join(' '));
  const normalizedKeyword = normalizeText(mainKeyword);
  const headingH1Count = (content.match(/^#\s+/gm) || []).length;
  const headingH2Count = (content.match(/^##\s+/gm) || []).length;

  const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
  const links = [];
  let linkMatch;
  while ((linkMatch = linkRegex.exec(content)) !== null) {
    const url = (linkMatch[2] || '').trim();
    if (!url) continue;
    links.push(url);
  }
  const internalDomain = (requestBody.internal_domain || '').toString().trim().toLowerCase();
  const totalLinks = links.length;
  const internalLinks = links.filter(url => url.startsWith('/') || (internalDomain && url.toLowerCase().includes(internalDomain))).length;
  const externalLinks = totalLinks - internalLinks;

  const mainOccurrences = countOccurrences(normalizedContent, normalizedKeyword);
  const keywordDensity = finalWordCount ? (mainOccurrences / finalWordCount) * 100 : 0;
  const keywordDensityRounded = Math.round(keywordDensity * 100) / 100;
  const keywordInIntro = firstHundred ? countOccurrences(firstHundred, normalizedKeyword) > 0 : false;

  const secondaryStats = {};
  secondaryKeywords.forEach((kw) => {
    const norm = normalizeText(kw);
    if (!norm) return;
    secondaryStats[kw] = countOccurrences(normalizedContent, norm);
  });

  const checks = [];
  function addCheck(id, label, status, message, options = {}) {
    checks.push({
      id,
      label,
      status,
      message,
      critical: options.critical !== false,
      value: options.value,
      expected: options.expected,
      details: options.details
    });
  }

  if (!metaTitle) {
    addCheck('meta_title_presence', 'Meta Title', 'fail', 'Meta title vac?o.', { value: 0, expected: `${metaTitleMin}-${metaTitleMax} caracteres` });
  } else {
    const len = metaTitle.length;
    if (len > metaTitleMax) {
      addCheck('meta_title_length', 'Meta Title', 'fail', `Meta title con ${len} caracteres, excede ${metaTitleMax}.`, { value: len, expected: `${metaTitleMin}-${metaTitleMax}` });
    } else if (len < metaTitleMin) {
      const status = len >= metaTitleWarnMin ? 'warn' : 'fail';
      addCheck('meta_title_length', 'Meta Title', status, `Meta title con ${len} caracteres, por debajo de ${metaTitleMin}.`, { value: len, expected: `${metaTitleMin}-${metaTitleMax}` });
    } else {
      addCheck('meta_title_length', 'Meta Title', 'pass', `Meta title con ${len} caracteres.`, { value: len, expected: `${metaTitleMin}-${metaTitleMax}` });
    }
  }

  if (!metaDescription) {
    addCheck('meta_description_presence', 'Meta Description', 'fail', 'Meta description vac?a.', { value: 0, expected: `${metaDescriptionMin}-${metaDescriptionMax} caracteres` });
  } else {
    const len = metaDescription.length;
    if (len > metaDescriptionMax) {
      addCheck('meta_description_length', 'Meta Description', 'fail', `Meta description con ${len} caracteres, excede ${metaDescriptionMax}.`, { value: len, expected: `${metaDescriptionMin}-${metaDescriptionMax}` });
    } else if (len < metaDescriptionMin) {
      const status = len >= metaDescriptionWarnMin ? 'warn' : 'fail';
      addCheck('meta_description_length', 'Meta Description', status, `Meta description con ${len} caracteres, menor a ${metaDescriptionMin}.`, { value: len, expected: `${metaDescriptionMin}-${metaDescriptionMax}` });
    } else {
      addCheck('meta_description_length', 'Meta Description', 'pass', `Meta description con ${len} caracteres.`, { value: len, expected: `${metaDescriptionMin}-${metaDescriptionMax}` });
    }
  }

  if (finalWordCount >= wordCountMin) {
    addCheck('word_count', 'Word Count', 'pass', `Word count ${finalWordCount}.`, { value: finalWordCount, expected: `>= ${wordCountMin}` });
  } else if (finalWordCount >= wordCountWarn) {
    addCheck('word_count', 'Word Count', 'warn', `Word count ${finalWordCount}, ligeramente por debajo del objetivo ${wordCountMin}.`, { value: finalWordCount, expected: `>= ${wordCountMin}` });
  } else {
    addCheck('word_count', 'Word Count', 'fail', `Word count ${finalWordCount}, insuficiente para el m?nimo ${wordCountMin}.`, { value: finalWordCount, expected: `>= ${wordCountMin}` });
  }

  if (headingH1Count > 0) {
    addCheck('heading_h1', 'Encabezados H1', 'pass', 'Se detect? al menos un H1.', { value: headingH1Count, expected: '>= 1' });
  } else {
    addCheck('heading_h1', 'Encabezados H1', 'fail', 'No se encontr? H1 en el contenido.', { value: headingH1Count, expected: '>= 1' });
  }

  if (headingH2Count > 0) {
    addCheck('heading_h2', 'Encabezados H2', 'pass', 'Se detect? al menos un H2.', { value: headingH2Count, expected: '>= 1' });
  } else {
    addCheck('heading_h2', 'Encabezados H2', 'fail', 'No se encontr? H2 en el contenido.', { value: headingH2Count, expected: '>= 1' });
  }

  if (!normalizedKeyword) {
    addCheck('keyword_primary', 'Keyword principal', 'warn', 'No se recibi? keyword principal para evaluar.', { critical: false });
  } else if (keywordInIntro) {
    addCheck('keyword_in_intro', 'Keyword en introducci?n', 'pass', 'La keyword principal aparece en los primeros 100 t?rminos.', { value: true });
  } else {
    addCheck('keyword_in_intro', 'Keyword en introducci?n', 'fail', 'La keyword principal no aparece en los primeros 100 t?rminos.', { value: false });
  }

  if (!normalizedKeyword) {
    addCheck('keyword_density', 'Densidad de keyword', 'warn', 'Sin keyword principal no se puede calcular densidad.', { critical: false });
  } else {
    if (keywordDensityRounded >= densityMin && keywordDensityRounded <= densityMax) {
      addCheck('keyword_density', 'Densidad de keyword', 'pass', `Densidad ${keywordDensityRounded.toFixed(2)}%.`, { value: keywordDensityRounded, expected: `${densityMin}-${densityMax}%` });
    } else if ((keywordDensityRounded >= densityWarnMin && keywordDensityRounded < densityMin) || (keywordDensityRounded > densityMax && keywordDensityRounded <= densityWarnMax)) {
      addCheck('keyword_density', 'Densidad de keyword', 'warn', `Densidad ${keywordDensityRounded.toFixed(2)}%, fuera del rango ideal pero aceptable.`, { value: keywordDensityRounded, expected: `${densityMin}-${densityMax}%` });
    } else {
      addCheck('keyword_density', 'Densidad de keyword', 'fail', `Densidad ${keywordDensityRounded.toFixed(2)}%, fuera de rango.`, { value: keywordDensityRounded, expected: `${densityMin}-${densityMax}%` });
    }
  }

  if (mainOccurrences > 0) {
    addCheck('keyword_occurrences', 'Ocurrencias keyword principal', 'pass', `Se encontraron ${mainOccurrences} apariciones.`, { value: mainOccurrences, expected: '> 0' });
  } else if (normalizedKeyword) {
    addCheck('keyword_occurrences', 'Ocurrencias keyword principal', 'fail', 'No se detectaron apariciones de la keyword principal.', { value: mainOccurrences, expected: '> 0' });
  }

  if (totalLinks > 0) {
    addCheck('links_total', 'Total de links', 'pass', `Se encontraron ${totalLinks} enlaces.`, { value: totalLinks, expected: '>= 1', critical: false });
  } else {
    addCheck('links_total', 'Total de links', 'warn', 'No se detectaron enlaces en el art?culo.', { value: totalLinks, expected: '>= 1', critical: false });
  }

  if (internalLinks > 0) {
    addCheck('links_internal', 'Links internos', 'pass', `Se detectaron ${internalLinks} enlaces internos.`, { value: internalLinks, expected: '>= 1', critical: false });
  } else {
    addCheck('links_internal', 'Links internos', 'warn', 'No se detectaron enlaces internos (opcional).', { value: internalLinks, expected: '>= 1', critical: false });
  }

  if (tags.length > 0) {
    addCheck('tags_presence', 'Tags', 'pass', `Se definieron ${tags.length} tags.`, { value: tags.length, expected: '>= 1', critical: false });
  } else {
    addCheck('tags_presence', 'Tags', 'warn', 'No se definieron tags para el draft.', { value: tags.length, expected: '>= 1', critical: false });
  }

  const criticalFailures = checks.filter(check => check.critical !== false && check.status === 'fail');
  const warnings = checks.filter(check => check.status === 'warn');
  const qaPassed = criticalFailures.length === 0;
  const qaStatus = qaPassed ? (warnings.length ? 'pass_with_warnings' : 'pass') : 'fail';
  const summaryMessage = qaPassed ? (warnings.length ? 'QA aprobado con observaciones.' : 'QA aprobado.') : 'QA rechazado: revisar checks cr?ticos.';

  const summary = {
    total_checks: checks.length,
    passed: checks.filter(check => check.status === 'pass').length,
    warnings: warnings.length,
    failed: checks.filter(check => check.status === 'fail').length,
    critical_failed: criticalFailures.map(check => ({ id: check.id, label: check.label, message: check.message })),
    message: summaryMessage
  };

  const stats = {
    word_count: finalWordCount,
    calculated_word_count: calculatedWordCount,
    stored_word_count: Number(data.word_count) || null,
    heading_h1: headingH1Count,
    heading_h2: headingH2Count,
    keyword_occurrences: mainOccurrences,
    keyword_density: Number(keywordDensityRounded.toFixed(2)),
    keyword_in_intro: keywordInIntro,
    links_total: totalLinks,
    links_internal: internalLinks,
    links_external: externalLinks,
    tags_total: tags.length,
    secondary_keyword_occurrences: secondaryStats
  };

  const qaCheckedAt = new Date().toISOString();

  const qaReport = {
    generated_at: qaCheckedAt,
    summary,
    stats,
    checks,
    context: {
      draft_id: data.draft_id,
      idea_id: data.idea_id,
      keyword_cluster_id: data.keyword_cluster_id,
      keyword_principal: mainKeyword,
      project_name: data.project_name
    }
  };

  return {
    json: {
      ...data,
      qa_report: qaReport,
      qa_passed: qaPassed,
      qa_status: qaStatus,
      qa_checked_at: qaCheckedAt
    }
  };
});

const idx = $itemIndex;
const context = $items('Evaluar QA', 0)[idx]?.json || {};
const updatedDraft = $json || {};

return [{
  json: {
    ...context,
    updated_draft: updatedDraft
  }
}];

const context = $json || {};
const endTime = new Date();
const durationMs = Math.max(0, Date.now() - (context.start_ts_ms || Date.now()));
const checks = context.qa_report?.checks || [];
const warnings = checks.filter(check => check.status === 'warn').map(check => ({ id: check.id, message: check.message }));
const failures = checks.filter(check => check.status === 'fail').map(check => ({ id: check.id, message: check.message }));

const jobLog = {
  job_name: 'SEO - 13 QA SEO',
  job_type: 'qa',
  status: 'success',
  related_keyword_id: context.keyword_cluster_id || null,
  related_idea_id: context.idea_id || null,
  related_draft_id: context.draft_id || null,
  started_at: context.start_time || endTime.toISOString(),
  completed_at: endTime.toISOString(),
  duration_ms: durationMs,
  input_data: {
    filters: context.request_body || {},
    draft_status: context.draft_status,
    project_name: context.project_name,
    keyword_principal: context.keyword_principal
  },
  output_data: {
    qa_passed: context.qa_passed,
    qa_status: context.qa_status,
    summary: context.qa_report?.summary || {},
    stats: context.qa_report?.stats || {},
    warnings,
    failures
  }
};

return [{
  json: {
    ...context,
    job_log: jobLog
  }
}];

const idx = $itemIndex;
const context = $items('Preparar Job Log QA', 0)[idx]?.json || {};
const jobLogRow = $json || {};

return [{
  json: {
    ...context,
    job_log_id: jobLogRow.id || null,
    job_log_created_at: jobLogRow.created_at || null
  }
}];

const context = $json || {};
const checks = context.qa_report?.checks || [];
const warnings = checks.filter(check => check.status === 'warn').map(check => ({ id: check.id, message: check.message }));
const failures = checks.filter(check => check.status === 'fail').map(check => ({ id: check.id, message: check.message }));

return [{
  json: {
    draft_id: context.draft_id,
    idea_id: context.idea_id,
    keyword_cluster_id: context.keyword_cluster_id,
    cluster_name: context.cluster_name,
    project_name: context.project_name,
    keyword_principal: context.keyword_principal,
    qa_passed: context.qa_passed,
    qa_status: context.qa_status,
    qa_checked_at: context.qa_checked_at,
    qa_report: context.qa_report,
    qa_summary: context.qa_report?.summary || {},
    qa_stats: context.qa_report?.stats || {},
    warnings,
    failures,
    job_log_id: context.job_log_id,
    tags: context.tags,
    word_count: context.qa_report?.stats?.word_count ?? context.word_count
  }
}];

const items = $json.processed_items || [];
const total = items.length;
const totalPassed = items.filter(item => item.qa_passed).length;
const totalWarnings = items.filter(item => item.qa_status === 'pass_with_warnings').length;
const totalFailed = total - totalPassed;

return [{
  json: {
    status: total ? 'success' : 'empty',
    summary: {
      total,
      passed: totalPassed,
      warnings: totalWarnings,
      failed: totalFailed
    },
    drafts: items.map(item => ({
      draft_id: item.draft_id,
      idea_id: item.idea_id,
      keyword_cluster_id: item.keyword_cluster_id,
      cluster_name: item.cluster_name,
      qa_passed: item.qa_passed,
      qa_status: item.qa_status,
      qa_checked_at: item.qa_checked_at,
      qa_stats: item.qa_stats,
      warnings: item.warnings,
      failures: item.failures,
      job_log_id: item.job_log_id
    })),
    generated_at: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'empty',
    message: 'No hay drafts pendientes de QA.',
    generated_at: new Date().toISOString()
  }
}];
